import { TrackProps } from './tracks.js';
import { WithId } from '../../../types/with-id.js';
/**
 * @internal
 */
export type AnnotationData = WithId<Annotation> & Omit<TrackProps, 'markers'>;
export interface Annotation {
    /** Start date of annotation. */
    start: Date;
    /** End date of annotation. */
    end?: Date;
    /** Title of the annotation. */
    title: string;
    /** Details about the annotation. */
    description?: string;
}
export interface AnnotationGroup {
    /** Group priority */
    priority: number;
    /** Annotations group */
    annotations: AnnotationData[];
    /** Group key */
    key: string;
    start: Date;
    end: Date;
}
